get_ecommerce_settings.code:
import {ecommerceSettings} from 'webcommander-sdk';

const response = await ecommerceSettings.getEcommerceSettings(client);
const settings = response.map.ecommerce_settings;
console.log(settings.continue_shopping.continue_shopping_target);
console.log(settings.order_filters.default_payment_status, settings.order_filters.default_shipment_status);

patch_ecommerce_settings.code:
import {ecommerceSettings} from 'webcommander-sdk';

const response = await ecommerceSettings.patchEcommerceSettings(client, {
    ecommerce_settings: {
        continue_shopping: {continue_shopping_target: 'previous'},
        order_filters: {default_payment_status: 'unpaid'},
    },
});
const settings = response.map.ecommerce_settings;
console.log(settings.continue_shopping.continue_shopping_target);
console.log(settings.order_filters.default_payment_status);

