get_ecommerce_settings_section.code:
import {ecommerceSettings} from 'webcommander-sdk';

const response = await ecommerceSettings.getEcommerceSettingsSection(client, 'order_filters');
const filters = response.map.order_filters;
console.log(filters.default_order_status, filters.default_payment_status, filters.default_shipment_status);

patch_ecommerce_settings_section.code:
import {ecommerceSettings} from 'webcommander-sdk';

const response = await ecommerceSettings.patchEcommerceSettingsSection(client, 'order_filters', {
    order_filters: {default_shipment_status: 'unshipped'},
});
console.log(response.map.order_filters.default_shipment_status);
